"use client";
import { useState } from 'react';
import { getWalletClient } from '@/lib/client';
import ClaimHandle from '@/components/ClaimHandle';

export default function Home() {
  const [account, setAccount] = useState<string | null>(null);

  const connect = async () => {
    const client = await getWalletClient();
    if (client) {
      const [address] = await client.requestAddresses();
      setAccount(address);
    }
  };

  return (
    <main className="min-h-screen bg-black text-white p-6">
      <div className="max-w-xl mx-auto">
        <header className="flex justify-between items-center mb-10">
          <h1 className="text-3xl font-black italic">HARD FORK</h1>
          <button onClick={connect} className="bg-zinc-800 px-4 py-2 rounded-full text-sm font-bold">
            {account ? `${account.slice(0,6)}...` : "Connect Wallet"}
          </button>
        </header>

        {account && <ClaimHandle account={account} />}

        {/* This is the Feed Placeholder */}
        <div className="mt-10 space-y-6">
          <div className="bg-zinc-900 rounded-3xl overflow-hidden border border-zinc-800">
            <div className="h-64 bg-gradient-to-br from-blue-900 to-black p-8 flex items-end">
              <h2 className="text-2xl font-bold">First Venture Post</h2>
            </div>
            <div className="p-6">
              <p className="text-zinc-400">Claim your handle above to start investing in the future.</p>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}