"use client";
import { useState } from 'react';
import { getWalletClient } from '@/lib/client';

const REGISTRY_ABI = [
  {
    name: 'registerProfile',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: '_username', type: 'string' },
      { name: '_metadataCID', type: 'string' }
    ],
    outputs: [],
  }
] as const;

export default function ClaimHandle({ account }: { account: string }) {
  const [username, setUsername] = useState('');
  const [loading, setLoading] = useState(false);

  const claim = async () => {
    if (!username || username.length < 3) return alert("Username too short");
    setLoading(true);
    try {
      const client = await getWalletClient();
      if (!client) return;
      const hash = await client.writeContract({
        address: process.env.NEXT_PUBLIC_REGISTRY_ADDR as `0x${string}`,
        abi: REGISTRY_ABI,
        functionName: 'registerProfile',
        args: [username, "ipfs://default-avatar"],
        account: account as `0x${string}`,
      });
      alert(`Handle @${username} claimed!`);
    } catch (e: any) {
      alert("Error claiming handle. It might be taken.");
    } finally { setLoading(false); }
  };

  return (
    <div className="bg-zinc-900 p-6 rounded-2xl border border-zinc-800 shadow-xl">
      <h3 className="text-xl font-bold mb-4 text-white">Join Hard Fork</h3>
      <div className="flex gap-2">
        <input 
          value={username}
          onChange={(e) => setUsername(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ''))}
          className="flex-1 bg-black border border-zinc-700 rounded-xl py-3 px-4 text-white outline-none focus:border-blue-500"
          placeholder="Choose handle (e.g. balson)"
        />
        <button onClick={claim} disabled={loading} className="bg-blue-600 px-6 rounded-xl font-bold hover:bg-blue-700">
          {loading ? "..." : "Claim"}
        </button>
      </div>
    </div>
  );
}